export { assertCiWorkflowUpToDate }
export { getCiWorkflow }
export { getGitHubRepo }
export { getWorkflowLink }
export { initCommand }
export { parseGitHubRepo }
export { releaseWorkflowFileName }
export { writeReleaseWorkflow }
export type { CiWorkflow }

// The GitHub Action that publishes to npm, see https://github.com/brillout/release-me#github-action
// - .github/workflows/release.yml is generated by `$ pnpm exec release-me init-github-action`, and must stay identical to what the command generates (no drift).
// - It calls the reusable workflow brillout/release-me/.github/workflows/publish.yml which does the actual work.

import * as fs from 'fs'
import * as path from 'path'
import execa from 'execa'
import pc from '@brillout/picocolors'

const releaseWorkflowFileName = 'release.yml'
const initCommand = '$ pnpm exec release-me init-github-action'
const releaseWorkflowContent = [
  `# Generated by \`${initCommand}\`. Don't modify it: release-me checks that it's up-to-date (re-run the command to update it).`,
  '# It publishes to npm using trusted publishing, see https://github.com/brillout/release-me#github-action',
  'name: Release',
  'on:',
  '  push:',
  "    tags: ['v[0-9]*', '**@[0-9]*'] # v1.2.3, some-package@1.2.3",
  '  workflow_dispatch:',
  '    inputs:',
  "      commit: { description: 'Commit: SHA, branch, or refs/pull/<number>/head (default: the selected branch)' }",
  "      package: { description: 'Package (default: all)' }",
  'permissions:',
  '  contents: read',
  '  id-token: write',
  'jobs:',
  '  release:',
  '    uses: brillout/release-me/.github/workflows/publish.yml@main',
  '',
].join('\n')

type CiWorkflow = {
  /** Workflow file name, i.e. `release.yml` */
  fileName: string
  /** GitHub repository, e.g. `vikejs/vike` */
  repo: string | null
}

/** Whether the repository publishes to npm via the GitHub Action (instead of locally) */
async function getCiWorkflow(monorepoRootDir: string): Promise<CiWorkflow | null> {
  if (getWorkflowFilesCallingPublish(monorepoRootDir).length === 0) return null
  return { fileName: releaseWorkflowFileName, repo: await getGitHubRepo(monorepoRootDir) }
}

function assertCiWorkflowUpToDate(monorepoRootDir: string) {
  const hint = `Run ${pc.bold(initCommand)} and commit the result.`
  const others = getWorkflowFilesCallingPublish(monorepoRootDir).filter((f) => f !== releaseWorkflowFileName)
  if (others.length > 0) {
    const files = others.map((f) => `.github/workflows/${f}`).join(' and ')
    throw new Error(
      [
        pc.red(
          pc.bold(
            `Release aborted, because ${files} ${
              others.length === 1 ? 'calls' : 'call'
            } release-me's reusable workflow publish.yml, but only .github/workflows/${releaseWorkflowFileName} should.`,
          ),
        ),
        `Remove ${others.length === 1 ? 'it' : 'them'}, then run ${pc.bold(initCommand)} and commit the result.`,
      ].join(' '),
    )
  }
  const content = readReleaseWorkflow(monorepoRootDir)
  if (content !== releaseWorkflowContent) {
    throw new Error(
      [
        pc.red(
          pc.bold(
            `Release aborted, because .github/workflows/${releaseWorkflowFileName} ${
              content === null ? 'is missing' : "isn't up-to-date (or was modified)"
            }.`,
          ),
        ),
        hint,
      ].join(' '),
    )
  }
}

/** Create or update .github/workflows/release.yml */
function writeReleaseWorkflow(monorepoRootDir: string): 'created' | 'updated' | 'up-to-date' {
  const content = readReleaseWorkflow(monorepoRootDir)
  if (content === releaseWorkflowContent) return 'up-to-date'
  const filePath = path.join(getWorkflowsDir(monorepoRootDir), releaseWorkflowFileName)
  if (content !== null && !callsPublish(content)) {
    // Don't overwrite a release.yml that has nothing to do with release-me
    throw new Error(
      pc.red(
        pc.bold(
          `${filePath} already exists and it isn't release-me's (it doesn't call release-me's reusable workflow publish.yml): rename or remove it, then re-run ${initCommand}.`,
        ),
      ),
    )
  }
  fs.mkdirSync(path.dirname(filePath), { recursive: true })
  fs.writeFileSync(filePath, releaseWorkflowContent)
  return content === null ? 'created' : 'updated'
}

function readReleaseWorkflow(monorepoRootDir: string): string | null {
  try {
    const content = fs.readFileSync(path.join(getWorkflowsDir(monorepoRootDir), releaseWorkflowFileName), 'utf8')
    // Git may check out the file with CRLF line endings (Windows)
    return content.replace(/\r\n/g, '\n')
  } catch {
    return null
  }
}

/** The workflow files that call the reusable workflow brillout/release-me/.github/workflows/publish.yml (or a fork's) */
function getWorkflowFilesCallingPublish(monorepoRootDir: string): string[] {
  const workflowsDir = getWorkflowsDir(monorepoRootDir)
  let fileNames: string[]
  try {
    fileNames = fs.readdirSync(workflowsDir).sort()
  } catch {
    return []
  }
  return fileNames.filter((f) => {
    if (!/\.ya?ml$/.test(f)) return false
    const filePath = path.join(workflowsDir, f)
    return fs.statSync(filePath).isFile() && callsPublish(fs.readFileSync(filePath, 'utf8'))
  })
}
function callsPublish(workflowContent: string) {
  return /^\s*(?:-\s*)?uses:\s*['"]?[\w.-]+\/release-me\/\.github\/workflows\/publish\.ya?ml@/m.test(workflowContent)
}
function getWorkflowsDir(monorepoRootDir: string) {
  return path.join(monorepoRootDir, '.github', 'workflows')
}

async function getGitHubRepo(cwd: string): Promise<string | null> {
  let remoteUrl: string
  try {
    remoteUrl = (await execa('git', ['remote', 'get-url', 'origin'], { cwd })).stdout.trim()
  } catch {
    return null
  }
  return parseGitHubRepo(remoteUrl)
}
function parseGitHubRepo(url: string): string | null {
  // git@github.com:vikejs/vike.git
  // https://github.com/vikejs/vike
  // git+https://github.com/vikejs/vike.git
  // ssh://git@github.com/vikejs/vike.git
  const match = /github\.com[:/]([\w.-]+\/[\w.-]+?)(?:\.git)?\/?$/.exec(url)
  return match?.[1] ?? null
}

function getWorkflowLink(ciWorkflow: CiWorkflow): string {
  const { fileName, repo } = ciWorkflow
  if (!repo) return pc.bold(`.github/workflows/${fileName}`)
  return pc.underline(`https://github.com/${repo}/actions/workflows/${fileName}`)
}
